import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { deleteProductCategoriesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await deleteProductCategoriesWorkflow(req.scope)
    .run({
      input: ["pcat_123"]
    })

  res.send(result)
}

